reg [3:0] state;
reg [9:0] cycle_cnt;
reg [3:0] delay;
reg [3:0] next_state;

assign count = delay;
always @(*) begin
    if (state == 0 && data == 1)
        next_state = 1;
    else if (state == 0 && data == 0)
        next_state = 0;
    else if (state == 1 && data == 1)
        next_state = 2;
    else if (state == 1 && data == 0)
        next_state = 0;
    else if (state == 2 && data == 0)
        next_state = 3;
    else if (state == 2 && data == 1)
        next_state = 2;
    else if (state == 3 && data == 1)
        next_state = 4;
    else if (state == 3 && data == 0)
        next_state = 0;
    else if (state == 4)
        next_state = 5;
    else if (state == 5)
        next_state = 6;
    else if (state == 6)
        next_state = 7;
    else if (state == 7)
        next_state = 8;
    else if (state == 8 && cycle_cnt == 999 && delay == 0)
        next_state = 9;
    else if (state == 8)
        next_state = 8;
    else if (state == 9 && ack == 1)
        next_state = 0;
    else if (state == 9 && ack == 0)
        next_state = 9;
    else
        next_state = 0;
end

always @(posedge clk) begin
    begin
        if (reset)
            state <= 0;
        else
            state <= next_state;
    end
end
always @(posedge clk) begin
    begin
        if (reset)
            delay <= 0;
        else if (state == 4)
            delay <= {delay[2:0], data};
        else if (state == 5)
            delay <= {delay[2:0], data};
        else if (state == 6)
            delay <= {delay[2:0], data};
        else if (state == 7)
            delay <= {delay[2:0], data};
        else if (state == 8 && cycle_cnt == 999 && delay != 0)
            delay <= delay - 1;
        else
            delay <= delay;
    end
end
always @(posedge clk) begin
    begin
        if (reset)
            cycle_cnt <= 0;
        else if (state == 8 && cycle_cnt == 999)
            cycle_cnt <= 0;
        else if (state == 8)
            cycle_cnt <= cycle_cnt + 1;
        else
            cycle_cnt <= 0;
    end
end
always @(posedge clk) begin
    begin
        if (reset)
            counting <= 0;
        else if (state == 7)
            counting <= 1;
        else if (state == 8 && cycle_cnt == 999 && delay == 0)
            counting <= 0;
        else
            counting <= counting;
    end
end
always @(posedge clk) begin
    begin
        if (reset)
            done <= 0;
        else if (state == 8 && cycle_cnt == 999 && delay == 0)
            done <= 1;
        else if (state == 9 && ack == 1)
            done <= 0;
        else
            done <= done;
    end
end

endmodule
